/**
 * Vendix brand PWA icons (generated).
 *
 * Estos PNG son la marca Vendix a color y son el FALLBACK obligatorio de
 * `PublicPwaService.resolveIconBuffer()` cuando un tenant no tiene un logo
 * de branding valido en S3 (o cuando la derivacion del icono falla).
 *
 * Se embeben como base64 a proposito: los originales viven en
 * `apps/frontend/public/icons/` y NO existen dentro de la imagen Docker del
 * backend, y `nest-cli.json` no declara `compilerOptions.assets`, asi que
 * copiarlos a disco no sobreviviria al build. Embebidos funcionan igual en
 * dev (swc watch) y en produccion (dist), sin tocar la configuracion de build.
 *
 * Origen y optimizacion (sharp, PNG paletizado):
 *   - ICON_192: apps/frontend/public/icons/vendix-192.png -> 192x192
 *   - ICON_512: apps/frontend/public/icons/vendix-512.png -> 512x512
 *   - APPLE_TOUCH_180: apps/frontend/public/icons/apple-touch-icon.png -> 180x180
 *
 * Para regenerarlos, re-optimizar los PNG de origen con sharp
 * (`.png({ compressionLevel: 9, effort: 10, palette: true, quality: 90 })`)
 * y volver a volcar el base64 aqui.
 */

export const VENDIX_ICON_192_BASE64 =
  '';

export const VENDIX_ICON_512_BASE64 =
  '';

export const VENDIX_APPLE_TOUCH_180_BASE64 =
  '';
